function astar(grid, start, goal) {
  const rows = grid.length, cols = grid[0].length;
  const key = (r, c) => r + ',' + c;
  const heuristic = (r, c) => Math.abs(r - goal[0]) + Math.abs(c - goal[1]);
  const open = [[heuristic(start[0], start[1]), 0, start]];
  const gScore = { [key(start[0], start[1])]: 0};
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  while (open.length) {
    open.sort((a, b) => a[0] - b[0]);
    const [, g, [r, c]] = open.shift();
    if (r === goal[0] && c === goal[1]) return g;
    for (const [dr, dc] of dirs) {
      const nr = r + dr, nc = c + dc;
      if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || grid[nr][nc] === 1) continue;
      const ng = g + 1;
      if (ng < (gScore[key(nr, nc)] ?? Infinity)) {
        gScore[key(nr, nc)] = ng;
        open.push([ng + heuristic(nr, nc), ng, [nr, nc]]);
      }
    }
  }
  return -1;
}

